def split_bill(items, people, tip_pct):
    # Calculate total food cost
    total_food = 0
    for item in items:
        total_food += item["price"]

    # Calculate food cost per person
    person_food = {person: 0 for person in people}
    for item in items:
        for eater in item["eaters"]:
            person_food[eater] += item["price"] / len(item["eaters"])

    # Calculate tip amount (percentage of total food)
    total_tip = (total_food * tip_pct) / 100

    # Calculate adjusted food cost including tip proportion
    for person in people:
        # Proportion of food cost for this person
        proportion = person_food[person] / total_food if total_food != 0 else 1 / len(people)
        # Add tip proportion (same as food proportion)
        person_food[person] += total_tip * proportion

    # Round to nearest cent
    for person in people:
        person_food[person] = round(person_food[person])

    return person_food
