def target_temp(schedule, now, tz, window_open):
    current_local = (now + tz) % 1440  # Convert to local time

    # If schedule is empty, return default
    if not schedule:
        return 18.0

    # Sort schedule by 'from' time
    sorted_schedule = sorted(schedule, key=lambda x: x['from'])

    # Find the interval with the largest 'from' <= current_local
    candidate = None
    for interval in sorted_schedule:
        if interval['from'] <= current_local:
            candidate = interval
        else:
            break

    # If no candidate, use the first interval
    if candidate is None:
        temp = sorted_schedule[0]['temp']
    else:
        temp = candidate['temp']

    # If window is open, reduce temperature (but not below 10°C)
